const { ethers } = require("ethers");
require("dotenv").config();
const { decideChains } = require("../../../config/provider");

// YOU MUST REPLACE THIS WITH YOUR NEW COMPILED BYTECODE
const SIMULATOR_BYTECODE =
  "";

const ROUTERS = {
  1: "0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D",
  56: "0x10ED43C718714eb63d5aA57B78B54704E256024E",
  8453: "0x327Df1E6de05895d2ab08513aaDD9313Fe505d86",
  42161: "0x1b02dA8Cb0d097eB8D57A175b88c7D8b47997506",
};

// EXACT Match to HoneypotBaseResult Struct
const SIMULATOR_ABI = [
  "function checkContract(address targetContract, address dexRouter) external payable returns (tuple(bool isBlackListDetected, bool isMintable, uint256 mintScore, string mintReason, bool isTradingControl, uint256 buyTax, uint256 sellTax, uint8 riskScore, string errorReason))",
];
const iface = new ethers.Interface(SIMULATOR_ABI);

const _runHoneypotCheck = async (contractAddress, chainId = 1) => {
  try {
    const { provider } = decideChains(chainId);
    const dexRouterAddress = ROUTERS[chainId];

    if (!dexRouterAddress)
      throw new Error("Unsupported DEX Router for this chain");

    const callData = iface.encodeFunctionData("checkContract", [
      contractAddress,
      dexRouterAddress,
    ]);

    const VITALIK_SENDER = ethers.getAddress(
      "0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045",
    );

    const stateOverride = {
      [VITALIK_SENDER]: {
        code: SIMULATOR_BYTECODE,
        balance: "0xffffffffffffffffffffffff",
      },
    };

    const intervals = [
      { label: "Immediate", delay: 0 },
      { label: "24 Hours", delay: 86400 },
      { label: "7 Days", delay: 604800 },
    ];

    let finalResult = {
      riskScore: 0,
      buyTax: 0,
      sellTax: 0,
      isTimeHoneypot: false,
      errorReason: "",
      timeTravelResults: [],
    };

    const now = Math.floor(Date.now() / 1000);

    for (const interval of intervals) {
      const futureTimestamp = now + interval.delay;

      const txObj = {
        from: VITALIK_SENDER,
        to: VITALIK_SENDER,
        data: callData,
        value: ethers.toBeHex(ethers.parseEther("0.1")),
        gas: "0x1C9C380",
        gasPrice: "0x0",
      };

      // The Time Travel Fix: Block Overrides as the 4th parameter
      const blockOverride = {
        timestamp: ethers.toBeHex(futureTimestamp),
      };

      const params = [txObj, "latest", stateOverride, blockOverride];

      try {
        const response = await provider.send("eth_call", params);

        if (!response || response === "0x") {
          throw new Error("Simulation reverted without data.");
        }

        const decoded = iface.decodeFunctionResult(
          "checkContract",
          response,
        )[0];

        // Mapping perfectly to your Solidity Tuple
        const result = {
          label: interval.label,
          isBlackListDetected: decoded[0],
          isMintable: decoded[1],
          mintScore: Number(decoded[2]),
          mintReason: decoded[3],
          isTradingControl: decoded[4],
          buyTax: Number(decoded[5]),
          sellTax: Number(decoded[6]),
          riskScore: Number(decoded[7]),
          errorReason: decoded[8],
        };

        // Aggregating extreme taxes into the risk score
        if (result.buyTax >= 90 || result.sellTax >= 90) {
          result.riskScore = 100;
          result.errorReason = "Honeypot: Extreme Taxes Detected";
        }

        finalResult.timeTravelResults.push(result);

        if (interval.delay === 0) {
          finalResult.buyTax = result.buyTax;
          finalResult.sellTax = result.sellTax;
          finalResult.riskScore = result.riskScore;
          finalResult.errorReason = result.errorReason;
        } else {
          if (
            result.riskScore > finalResult.riskScore ||
            result.buyTax > finalResult.buyTax + 10
          ) {
            finalResult.isTimeHoneypot = true;
            finalResult.riskScore = 100;
            finalResult.errorReason = `Time-Delayed Trap: ${result.errorReason}`;
          }
        }
      } catch (err) {
        console.warn(
          `[TxShield] Time Travel (${interval.label}) Failed:`,
          err.message,
        );

        if (interval.delay === 0) {
          finalResult.riskScore = 100;
          finalResult.errorReason = `Fatal Revert: Dead token or unverified assembly trap. (${err.message})`;
          break;
        }
      }
    }

    return {
      ...finalResult,
      buyingTax: finalResult.buyTax,
      sellingTax: finalResult.sellTax,
      hasBlackListDetected: false, // Default flags for UI compatibility
      hasMintable: false,
      hasTradingControl: false,
    };
  } catch (err) {
    console.error(`Honeypot Fatal Error: ${err.message}`);
    return {
      success: false,
      error: err.message,
      riskScore: 0,
      buyingTax: 0,
      sellingTax: 0,
      hasBlackListDetected: false,
      hasMintable: false,
      hasTradingControl: false,
    };
  }
};

module.exports = _runHoneypotCheck;
